import sys

def max_juice_drunk(n, moves):
    vasya_moves = []
    juice_count = 0

    for i, move in enumerate(moves):
        if i % n == 0:
            vasya_moves.append(move)

        if i >= 3:
            if vasya_moves[-1] == vasya_moves[-2] == vasya_moves[-3] == move:
                prev_move = moves[(i - 3) % len(moves)]
                if (move == 'a' and prev_move == 'b') or (move == 'b' and prev_move == 'a'):
                    juice_count += 1
                    vasya_moves = vasya_moves[:-3]

    return juice_count

def main():
    n = int(sys.stdin.readline().strip())
    moves = sys.stdin.readline().strip()

    result = max_juice_drunk(n, moves)
    print(result)

